import{_ as a,m as t,k as n,ah as i}from"./chunks/framework.HEc25T99.js";const g=JSON.parse('{"title":"FAQ","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"users/support/faq.md","filePath":"src/en/users/support/faq.md"}'),o={name:"users/support/faq.md"};function s(r,e,c,h,l,d){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p>Common questions about using the Creopse administration. If your question isn&#39;t here, contact your administrator.</p><h2 id="content-publishing" tabindex="-1">Content &amp; publishing <a class="header-anchor" href="#content-publishing" aria-label="Permalink to &quot;Content &amp; publishing&quot;">​</a></h2><h3 id="i-edited-a-section-but-nothing-changed-on-the-public-site" tabindex="-1">I edited a section but nothing changed on the public site <a class="header-anchor" href="#i-edited-a-section-but-nothing-changed-on-the-public-site" aria-label="Permalink to &quot;I edited a section but nothing changed on the public site&quot;">​</a></h3><p>You probably missed the publishing step: in the <a href="./../sections/visual-editor.html">Visual Editor</a>, changes only become publicly visible after clicking <strong>Publish</strong>. The <strong>Preview</strong> button lets you check the rendering before publishing.</p><h3 id="how-do-i-add-a-new-page-or-reorder-its-sections" tabindex="-1">How do I add a new page or reorder its sections? <a class="header-anchor" href="#how-do-i-add-a-new-page-or-reorder-its-sections" aria-label="Permalink to &quot;How do I add a new page or reorder its sections?&quot;">​</a></h3><p>From <a href="./../sections/content-management.html">Content Management</a>, the page list offers <strong>Add page</strong> and <strong>Rearrange pages</strong>. Once a page is selected, its sections can be reordered, shown/hidden, or edited directly.</p><h3 id="i-can-t-find-how-to-attach-a-new-section-to-a-page" tabindex="-1">I can&#39;t find how to attach a new section to a page <a class="header-anchor" href="#i-can-t-find-how-to-attach-a-new-section-to-a-page" aria-label="Permalink to &quot;I can&#39;t find how to attach a new section to a page&quot;">​</a></h3><p>From the page in question (in <a href="./../sections/content-management.html">Content Management</a>), the <strong>Insert or remove sections</strong> block lets you add one. The same action is also available from the <a href="./../sections/visual-editor.html">Visual Editor</a>.</p><h3 id="what-s-the-difference-between-an-article-s-statuses-draft-pending-published" tabindex="-1">What&#39;s the difference between an article&#39;s statuses (Draft, Pending, Published)? <a class="header-anchor" href="#what-s-the-difference-between-an-article-s-statuses-draft-pending-published" aria-label="Permalink to &quot;What&#39;s the difference between an article&#39;s statuses (Draft, Pending, Published)?&quot;">​</a></h3><p><strong>Draft</strong> is only visible to its author, <strong>Pending</strong> flags an article that&#39;s ready but awaiting approval, and <strong>Published</strong> is visible on the public site. See <a href="./../sections/news-management.html">News Management</a>.</p><h3 id="a-section-s-content-isn-t-showing-in-a-given-language" tabindex="-1">A section&#39;s content isn&#39;t showing in a given language <a class="header-anchor" href="#a-section-s-content-isn-t-showing-in-a-given-language" aria-label="Permalink to &quot;A section&#39;s content isn&#39;t showing in a given language&quot;">​</a></h3><p>Check that the corresponding field was actually filled in for that language — Creopse content is bilingual per field, a missing value in one language stays empty rather than automatically falling back to the other language.</p><h2 id="media" tabindex="-1">Media <a class="header-anchor" href="#media" aria-label="Permalink to &quot;Media&quot;">​</a></h2><h3 id="i-deleted-a-file-by-mistake-can-it-be-recovered" tabindex="-1">I deleted a file by mistake, can it be recovered? <a class="header-anchor" href="#i-deleted-a-file-by-mistake-can-it-be-recovered" aria-label="Permalink to &quot;I deleted a file by mistake, can it be recovered?&quot;">​</a></h3><p>Yes, as long as it hasn&#39;t been permanently deleted: the <strong>Trash</strong> tab in the <a href="./../sections/media-library.html">Media Library</a> groups deleted files and lets you restore them.</p><h2 id="users-access" tabindex="-1">Users &amp; access <a class="header-anchor" href="#users-access" aria-label="Permalink to &quot;Users &amp; access&quot;">​</a></h2><h3 id="how-do-i-add-a-new-administrator" tabindex="-1">How do I add a new administrator? <a class="header-anchor" href="#how-do-i-add-a-new-administrator" aria-label="Permalink to &quot;How do I add a new administrator?&quot;">​</a></h3><p>From <a href="./../sections/user-management.html">User Management</a>, the <strong>Add</strong> button creates a new account, which is then assigned a role from <a href="./../sections/access-management.html">Access management</a>.</p><h3 id="i-don-t-have-access-to-a-section-i-should-be-able-to-see" tabindex="-1">I don&#39;t have access to a section I should be able to see <a class="header-anchor" href="#i-don-t-have-access-to-a-section-i-should-be-able-to-see" aria-label="Permalink to &quot;I don&#39;t have access to a section I should be able to see&quot;">​</a></h3><p>This depends on the permissions tied to your role. Ask an administrator to check your role in <a href="./../sections/access-management.html">Access management</a>, or check your current role from <a href="./../sections/account-info.html">Account Information</a>.</p><h2 id="account" tabindex="-1">Account <a class="header-anchor" href="#account" aria-label="Permalink to &quot;Account&quot;">​</a></h2><h3 id="i-forgot-my-password" tabindex="-1">I forgot my password <a class="header-anchor" href="#i-forgot-my-password" aria-label="Permalink to &quot;I forgot my password&quot;">​</a></h3><p>Use the recovery link on the login page. Once logged in, the password can be changed at any time from <a href="./../sections/account-info.html">Account Information</a> (click the pencil icon next to the <strong>Password</strong> field).</p><h3 id="i-didn-t-receive-my-account-s-verification-email" tabindex="-1">I didn&#39;t receive my account&#39;s verification email <a class="header-anchor" href="#i-didn-t-receive-my-account-s-verification-email" aria-label="Permalink to &quot;I didn&#39;t receive my account&#39;s verification email&quot;">​</a></h3><p>Check your spam folder — the banner shown on the <a href="./../sections/dashboard.html">Overview</a> page also lets you resend the verification link.</p><h2 id="extensions" tabindex="-1">Extensions <a class="header-anchor" href="#extensions" aria-label="Permalink to &quot;Extensions&quot;">​</a></h2><h3 id="is-it-safe-to-install-a-plugin" tabindex="-1">Is it safe to install a plugin? <a class="header-anchor" href="#is-it-safe-to-install-a-plugin" aria-label="Permalink to &quot;Is it safe to install a plugin?&quot;">​</a></h3><p>A plugin has access to your site once installed — only install plugins from a source you trust. See <a href="./../sections/plugins.html">Extensions</a>.</p>',29)])])}const m=a(o,[["render",s]]);export{g as __pageData,m as default};
